package com.wansheng.visitor.auth;
import javax.crypto.SecretKey;import javax.crypto.spec.SecretKeySpec;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.security.authentication.AuthenticationManager;import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.crypto.factory.PasswordEncoderFactories;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.server.resource.authentication.*;import org.springframework.security.web.SecurityFilterChain;
@Configuration class SecurityConfiguration{
 @Bean PasswordEncoder passwordEncoder(){return PasswordEncoderFactories.createDelegatingPasswordEncoder();}@Bean UserDetailsService users(AccountRepository a){return a::loadUser;}@Bean AuthenticationManager authenticationManager(AuthenticationConfiguration c)throws Exception{return c.getAuthenticationManager();}
 @Bean SecretKey jwtKey(@Value("${visitor.security.jwt-secret}")String s){if(s.length()<32)throw new IllegalStateException("JWT secret must be at least 32 characters");return new SecretKeySpec(s.getBytes(java.nio.charset.StandardCharsets.UTF_8),"HmacSHA256");}@Bean JwtEncoder jwtEncoder(SecretKey k){return NimbusJwtEncoder.withSecretKey(k).build();}@Bean JwtDecoder jwtDecoder(SecretKey k){return NimbusJwtDecoder.withSecretKey(k).macAlgorithm(MacAlgorithm.HS256).build();}
 static JwtAuthenticationConverter converter(){var g=new JwtGrantedAuthoritiesConverter();g.setAuthoritiesClaimName("roles");g.setAuthorityPrefix("ROLE_");var c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(g);return c;}
 @Bean SecurityFilterChain authSecurity(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/api/visitor/auth/login").permitAll().requestMatchers("/api/visitor/auth/users/**").hasRole("SYSTEM_ADMIN").anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter()))).build();}
}
